SELECT a.point_code AS point_code, a.question_no AS question_no, COALESCE(a.answer, '') AS answer, a.at AS at, COALESCE((SELECT s.score FROM progress_score s WHERE s.learner = a.learner AND s.point_code = a.point_code AND s.subject_id = a.subject_id ORDER BY s.id DESC LIMIT 1), 0) AS score, COALESCE((SELECT m.mastered FROM progress_mastery m WHERE m.learner = a.learner AND m.point_code = a.point_code AND m.subject_id = a.subject_id), 0) AS mastered FROM progress_answer a WHERE a.learner = :learner AND a.subject_id = CAST(:subject_id AS INTEGER) AND a.correct = 0 ORDER BY a.id DESC LIMIT CAST(:limit AS INTEGER)
